const test = require('node:test');
const assert = require('node:assert/strict');
const crypto = require('../Crypto/NativeCryptoPrimitives');
// This offline primitive fixture uses the original fixture's public key.
const fixturePublicKey = '5F4BFA1DC7B58FAC0611F34DBAF3847B376F968530F76A9A202849017AA9510A';

// Generated by executing libg's native crypto_box (RVA 0x7af234) offline,
// after resolving protected calls; no game initialization or APK modification.
const expected = 'e4a5edc8600627f2f96241ac6cef752893391a9da26b18ce961aced1517553e16af83367a4c5ff1afc36e21eb8fda5f56f324c797a8f2ae85f9b5ffd66fd47cd149b5f9a2c3c669631da47ef1c081a81';
test('box encryption matches the actual native function', () => {
  const key = Uint8Array.from({length:32}, (_,i)=>i);
  const nonce = Uint8Array.from({length:24}, (_,i)=>i);
  const message = Uint8Array.from({length:64}, (_,i)=>i);
  const server = Buffer.from(fixturePublicKey,'hex');
  const boxed = crypto.box(message, nonce, server, key);
  assert.equal(boxed.toString('hex'), expected);
  assert.deepEqual(crypto.boxOpen(boxed, nonce, server, key), Buffer.from(message));
  boxed[0] ^= 1;
  assert.equal(crypto.boxOpen(boxed, nonce, server, key), null);
});
test('Blake2b matches the native compression fixture', () => {
  const message = Buffer.from(Array.from({length:64}, (_,i)=>i));
  assert.equal(crypto.blake2b24(message).toString('hex'), 'aa054507b4916837a6d2b35b1ce7c525facdb7868ed55a8a');
});
